14	// 三帧轨迹（含初始位姿）：
15	//
16	//	p0 (t=0)  (1,2)   h=0     v=0.5
17	//	p1 (t=100)(4,2)   h=π/2   v=0.75   观测 L1 本地(1,0) → 地图(4,3)
18	//	p2 (t=200)(4,4)   h=π/2   v=1.0    观测 L1 本地(0,0) → 地图(4,4)
19	//
20	// L1 为两次观测平均 (4,3.5)，次数 2。
21	func corrSegment() Segment {
22		return Segment{
23			ID: "s1",
24			Frames: []Frame{
25				{
26					Time: 100, DX: 3, DY: 0, DHeading: math.Pi / 2, MoveVariance: 0.25,
27					Observations: []Observation{{ID: "L1", X: 1, Y: 0}},
28				},
29				{
30					Time: 200, DX: 2, DY: 0, DHeading: 0, MoveVariance: 0.25,
31					Observations: []Observation{{ID: "L1", X: 0, Y: 0}, {ID: "M", X: 0, Y: 1}},
32				},
33			},
34		}
35	}
36	
37	func TestCorrectionRigidTransform(t *testing.T) {
38		m := newMap(t, baseConfig())
39		if _, err := m.ImportSegment(corrSegment()); err != nil {
40			t.Fatal(err)
41		}
42	
43		req := Correction{ID: "c1", Anchor: 100, Target: CorrectionTarget{X: 10, Y: 20, Heading: 0, Variance: 2}}
44		rec, err := m.Correct(req)
45		if err != nil {
46			t.Fatalf("Correct: %v", err)
47		}
48	
49		// 锚点 p1：精确采用目标位姿；δ = 0 - π/2 = -π/2。
50		// p2 相对锚点 (0,2) 旋转 -π/2 → (2,0)，新位置 (12,20)，朝向 0，
51		// 方差 = 2 + 原运动方差 0.25 = 2.25。
52		if rec.Anchor != 100 || rec.EndTime != 200 || len(rec.Poses) != 2 {
53			t.Fatalf("record header = %+v", rec)
54		}
55		got := rec.Poses
56		if got[0].Before.X != 4 || got[0].After.X != 10 || got[0].After.Y != 20 {
57			t.Fatalf("anchor pose change = %+v", got[0])
58		}
59		approxEq(t, "p2 after x", got[1].After.X, 12)
60		approxEq(t, "p2 after y", got[1].After.Y, 20)
61		approxEq(t, "p2 after heading", got[1].After.Heading, 0)
62		approxEq(t, "p2 after variance", got[1].After.Variance, 2.25)
63		approxEq(t, "anchor variance", got[0].After.Variance, 2)
64	
65		// 路标：p1 观测 → (11,20)，p2 观测 L1 → (12,20)，两次观测距离恰为
66		// 合并距离 1，可接受；平均 (11.5,20)，次数不变。
67		if len(rec.Landmarks) != 2 || rec.Landmarks[0].ID != "L1" || rec.Landmarks[1].ID != "M" {
68			t.Fatalf("landmark changes order = %+v", rec.Landmarks)
69		}
70		lc := rec.Landmarks[0]
71		approxEq(t, "L1 before x", lc.Before.X, 4)
72		approxEq(t, "L1 before y", lc.Before.Y, 3.5)
73		approxEq(t, "L1 after x", lc.After.X, 11.5)
74		approxEq(t, "L1 after y", lc.After.Y, 20)
75		if lc.Before.Count != 2 || lc.After.Count != 2 {
76			t.Fatalf("L1 count changed: %d -> %d", lc.Before.Count, lc.After.Count)
77		}
78	
79		// 更早的初始位姿不变。
80		p0, err := m.PoseAt(0)
81		if err != nil || p0.X != 1 || p0.Y != 2 || p0.Variance != 0.5 {
82			t.Fatalf("initial pose changed: %+v %v", p0, err)
83		}
84		// 当前位姿与历史查询立即返回校正结果（PoseAt 借用最近帧也一样）。
85		cur, _ := m.CurrentPose()
86		if cur.Time != 200 || cur.X != 12 || cur.Y != 20 {
87			t.Fatalf("current = %+v", cur)
88		}
89		p, _ := m.PoseAt(150)
90		if p.Time != 100 || p.X != 10 || p.Y != 20 {
91			t.Fatalf("pose at 150 = %+v, want corrected anchor", p)
92		}
93		lms, _ := m.LandmarksInRect(Rect{MinX: -1e9, MinY: -1e9, MaxX: 1e9, MaxY: 1e9})
94		if len(lms) != 2 {
95			t.Fatalf("landmarks = %v", lms)
96		}
97		for _, lm := range lms {
98			if lm.ID == "L1" {
99				approxEq(t, "queried L1 x", lm.X, 11.5)
100				approxEq(t, "queried L1 y", lm.Y, 20)
101				if lm.Count != 2 {
102					t.Fatalf("queried L1 count = %d", lm.Count)
103				}
104			}
105		}
106	
107		// 后续导入从校正后的末位姿接续：DX=1, 朝向 0 → (13,20)，方差 2.75。
