575			t.Fatalf("record leaked after failed save: %v", recs)
576		}
577		// 恢复文件后同标识校正可正常成功（记录此前未落盘）。
578		if err := os.Remove(path); err != nil {
579			t.Fatal(err)
580		}
581		if err := m.saveReplace(); err != nil {
582			t.Fatalf("restore save: %v", err)
583		}
584		if _, err := m.Correct(req); err != nil {
585			t.Fatalf("retry correction after failed save: %v", err)
586		}
587	}
