589	func TestCorrectionClosedMap(t *testing.T) {
590		m := newMap(t, baseConfig())
591		if err := m.Close(); err != nil {
592			t.Fatal(err)
593		}
594		if _, err := m.Correct(Correction{ID: "x", Anchor: 1, Target: CorrectionTarget{X: 1}}); !errors.Is(err, ErrClosed) {
595			t.Fatalf("correct on closed: %v", err)
